    VALUES ('TFSRWBFC-100', 'Rice water bright foaming cleanser', 'the-face-shop-rice-water-bright-foaming-cleanser', 1, 1,
    'Skincare', 'Cleanser', '100 ml',
    'Rice water bright foaming cleanser by The face shop — a cleanser curated for the modern skincare routine. A gentle yet effective cleanser that lifts away impurities, excess sebum and makeup residue while leaving skin soft, comfortable and balanced. Presented in a 100 ml size for consistent, everyday use.', 'A gentle yet effective cleanser that lifts away impurities, excess sebum and makeup residue while leaving skin soft, comfortable and balanced.', 749, 749, 35,
    175, 'published', 0, 0, 1, 0,
    4.6, 50, '["skincare","CellImage"]', '["Rice Water","Rice Bran Oil","Saponaria Officinalis Extract","Glycerin","Ceramide NP"]',
    '["Deep cleansing","Improves overall skin tone & texture","Suitable for daily use"]', 'Massage a small amount onto damp skin in gentle circular motions, then rinse thoroughly with lukewarm water. Use morning and evening.', '["Dry","Oily","Combination","Normal","Sensitive"]',
    '["Brightening"]', '["https://cdn.bdstall.com/product-image/450008_800X800.webp","https://static-01.daraz.com.bd/p/9ca50e7cae1ccd8e284cf1dbe1dde138.jpg"]', 'https://cdn.bdstall.com/product-image/450008_800X800.webp',
    'Rice water bright foaming cleanser — The face shop | Petal & Rose', 'A gentle yet effective cleanser that lifts away impurities, excess sebum and makeup residue while leaving skin soft, comfortable and balanced.');
