INSERT INTO products (sku, title, slug, brand_id, category_id, main_category, product_type, size,
    description, short_description, price, sale_price, discount_pct, stock, status, featured, best_seller,
    new_arrival, trending, rating, review_count, tags_json, ingredients_json, benefits_json, how_to_use,
    skin_types_json, concerns_json, images_json, thumbnail, seo_title, seo_description)
    VALUES ('TFSRCMC-50', 'Rice ceramide moisturizing cream', 'the-face-shop-rice-ceramide-moisturizing-cream', 1, 1,
    'Skincare', 'Cream', '50 ml',
    'Rice ceramide moisturizing cream by The face shop — a cream curated for the modern skincare routine. A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion. Presented in a 50 ml size for consistent, everyday use.', 'A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion.', 1249, 1249, 15,
    175, 'published', 1, 0, 0, 0,
    4.7, 50, '["skincare","CellImage"]', '["Rice Water","Rice Bran Oil","Saponaria Officinalis Extract","Glycerin","Ceramide NP"]',
    '["Deep hydration","Improves overall skin tone & texture","Suitable for daily use","Rice extract ও rice bran oil ত্বককে গভীরভাবে ময়েশ্চারাইজ করতে সহায়তা করে Ceramide NP ও glycosphingolipids ত্বকের ময়েশ্চার বেরিয়ার শক্তিশালী রাখতে সহায়তা করে Glycerin ও sodium hyaluronate ত্বকে হাইড্রেশন ধরে রাখতে সহায়তা করে Shea butter ও lecithin ত্বককে নরম ও কোমল রাখতে সহায়তা করে ত্বকের শুষ্ক ও টানটান ভাব কমিয়ে আরামদায়ক অনুভূতি দিতে সহায়তা করে রিচ কিন্তু সিল্কি টেক্সচার, তাই ভারী বা আঠালো ভাব না রেখেই ত্বকে মিশে যায় ত্বকের রুক্ষ ভাব কমিয়ে স্কিন টেক্সচার মসৃণ দেখাতে সহায়তা করে Paraben free, tar color free, mineral oil free ও talc free ফর্মুলা শুষ্ক আবহাওয়া বা এসির মধ্যে থাকলে ত্বকের ময়েশ্চার লস কমাতে সহায়তা করে"]', 'After serum, apply an even layer over the face and neck, gently pressing into skin until fully absorbed. Use morning and evening as the final step.', '["Dry","Oily","Combination","Normal","Sensitive"]',
    '["Hydration"]', '["https://au.thefaceshop.com/cdn/shop/files/RICE_CERAMIDECream.jpg?v=1753704558&width=1440","https://au.thefaceshop.com/cdn/shop/files/RICE_CERAMIDECream.jpg?v=1753704558&width=1440"]', 'https://au.thefaceshop.com/cdn/shop/files/RICE_CERAMIDECream.jpg?v=1753704558&width=1440',
    'Rice ceramide moisturizing cream — The face shop | Petal & Rose', 'A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion.');
INSERT INTO variants (product_id, sku, size, price, old_price, stock, image) VALUES (2, 'TFSRCMC-50', '50 ml', 1249, 1200, 175, 'https://au.thefaceshop.com/cdn/shop/files/RICE_CERAMIDECream.jpg?v=1753704558&width=1440');
