    '["Sun Protection","Soothing"]', '["https://kcbazar.com/wp-content/uploads/2025/03/SKIN1004-Madagascar-Centella-Hyalu-Cica-Water-Fit-Sun-Serum-Spf-50-PA-50-ml-2-1.jpg","https://kcbazar.com/wp-content/uploads/2025/03/SKIN1004-Madagascar-Centella-Hyalu-Cica-Water-Fit-Sun-Serum-Spf-50-PA-50-ml-2-1.jpg"]', 'https://kcbazar.com/wp-content/uploads/2025/03/SKIN1004-Madagascar-Centella-Hyalu-Cica-Water-Fit-Sun-Serum-Spf-50-PA-50-ml-2-1.jpg',
    'Centella Hyalu-Cica Water-Fit Sun Serum — Skin1004 | Petal & Rose', 'A concentrated treatment serum formulated to target your key skincare concerns with visible, results-driven actives.');
