    '["Sun Protection"]', '["https://static-01.daraz.com.bd/p/e14b57cb84a259b8b6906cf29e236419.jpg","https://static-01.daraz.com.bd/p/e14b57cb84a259b8b6906cf29e236419.jpg"]', 'https://static-01.daraz.com.bd/p/e14b57cb84a259b8b6906cf29e236419.jpg',
