    '["Hydration"]', '["https://majesticabd.com/wp-content/uploads/2026/07/file_00000000aeec71fdaa1e206852c34388-768x768.png","https://majesticabd.com/wp-content/uploads/2026/07/file_00000000aeec71fdaa1e206852c34388-768x768.png"]', 'https://majesticabd.com/wp-content/uploads/2026/07/file_00000000aeec71fdaa1e206852c34388-768x768.png',
