    '["Oil Control"]', '["https://kcbazar.com/wp-content/uploads/2024/06/Dabo-Green-Tomato-Poremide-Solution-Ampoule-80-ml-2.jpg","https://kcbazar.com/wp-content/uploads/2024/06/Dabo-Green-Tomato-Poremide-Solution-Ampoule-80-ml-2.jpg"]', 'https://kcbazar.com/wp-content/uploads/2024/06/Dabo-Green-Tomato-Poremide-Solution-Ampoule-80-ml-2.jpg',
