    VALUES ('MIS-PERFECTBB-23-50', 'Missha M Perfect Cover B.B Cream SPF42 / PA+++ No.23', 'missha-missha-m-perfect-cover-b-b-cream-spf42-pa-no-23', 14, 1,
    'Skincare', 'Cream', '50 ml',
    'Missha M Perfect Cover B.B Cream SPF42 / PA+++ No.23 by MISSHA — a cream curated for the modern skincare routine. A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion. Presented in a 50 ml size for consistent, everyday use.', 'A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion.', 1220, 1220, 26,
    3, 'published', 0, 0, 1, 0,
    4.3, 89, '["skincare","CellImage"]', '["Water, Cyclomethicone, Ethylhexyl Methoxycinnamate, Butylene Glycol, Zinc Oxide, Titanium Dioxide, Dimethicone, Cetyl PEG/PPG-10/1 Dimethicone, Glycerin, Magnesium Sulfate, Caprylic/Capric Triglyceride, Beeswax, Sodium Chloride, Fragrance, Phenoxyethanol, Methylparaben, Propylparaben, Adenosine, Sodium Hyaluronate, Ceramide 3, Rosemary Leaf Extract, Chamomile Flower Extract and other supporting ingredients."]',
    '["Deep hydration","Improves overall skin tone & texture","Suitable for daily use","SPF42 / PA+++ sun protection-এর মাধ্যমে UVA ও UVB exposure থেকে ত্বককে সুরক্ষিত রাখতে সাহায্য করে ত্বকের uneven tone ও minor imperfections-এর appearance cover করতে সাহায্য করে Redness ও discoloration-এর appearance কমিয়ে complexion আরও even-looking করতে সাহায্য করে Natural-looking coverage প্রদান করে No.23 Natural Beige shade ত্বকে natural-looking finish দিতে সাহায্য করে ত্বকের appearance আরও smooth ও polished দেখাতে সহায়তা করে Sodium Hyaluronate ত্বকের hydration বজায় রাখতে সাহায্য করে Ceramide skin-conditioning ও moisture barrier care-এ সহায়তা করে Adenosine ত্বকের overall conditioning care-এ সাহায্য করে Chamomile ও Rosemary extracts ত্বকের conditioning care-এ সহায়তা করে Makeup ও skincare-এর কিছু সুবিধা একসাথে প্রদান করে Daily makeup routine-এর জন্য উপযোগী ৫০ ml সাইজ হওয়ায় নিয়মিত ব্যবহারের জন্য সুবিধাজনক"]', 'Skincare routine সম্পন্ন করার পর মুখে অল্প পরিমাণ BB cream apply করুন। কপাল, গাল, নাক ও চিবুকে ছোট ছোট পরিমাণে নিয়ে আঙুল, makeup sponge অথবা brush দিয়ে পুরো মুখে সমানভাবে blend করুন। প্রয়োজনে coverage বাড়ানোর জন্য নির্দিষ্ট areas-এ দ্বিতীয় পাতলা layer apply করতে পারেন। এটি sunscreen-এর বিকল্প হিসেবে ব্যবহার না করে পর্যাপ্ত পরিমাণ dedicated sunscreen ব্যবহার করা ভালো, বিশেষ করে দীর্ঘ সময় বাইরে থাকলে।', '["Dry","Oily","Combination","Normal","Sensitive"]',
    '["Sun Protection"]', '["https://bk.shajgoj.com/storage/2022/07/Missha-M-Perfect-Cover-BB-Cream-SPF-42-PA-Natural-Beige-23_sku23779.jpg","https://bk.shajgoj.com/storage/2022/07/Missha-M-Perfect-Cover-BB-Cream-SPF-42-PA-Natural-Beige-23_sku23779.jpg"]', 'https://bk.shajgoj.com/storage/2022/07/Missha-M-Perfect-Cover-BB-Cream-SPF-42-PA-Natural-Beige-23_sku23779.jpg',
    'Missha M Perfect Cover B.B Cream SPF42 / PA+++ No.23 — MISSHA | Petal & Rose', 'A nourishing cream that floods skin with moisture and helps strengthen the skin barrier for a plump, healthy-looking complexion.');
INSERT INTO variants (product_id, sku, size, price, old_price, stock, image) VALUES (43, 'MIS-PERFECTBB-23-50', '50 ml', 1220, 1650, 3, 'https://bk.shajgoj.com/storage/2022/07/Missha-M-Perfect-Cover-BB-Cream-SPF-42-PA-Natural-Beige-23_sku23779.jpg');
