    VALUES ('TIA-DAILYSUN-50', 'TIAM Daily Sun Care Cream SPF50+ PA++++', 'tiam-tiam-daily-sun-care-cream-spf50-pa', 16, 1,
    'Skincare', 'Cream', '50 ml',
