    '["Sun Protection","Soothing"]', '["https://finelook.com/cdn/shop/files/Hyalu-CicaSunSerumTwinPack2.png?v=1740466747","https://finelook.com/cdn/shop/files/Hyalu-CicaSunSerumTwinPack2.png?v=1740466747"]', 'https://finelook.com/cdn/shop/files/Hyalu-CicaSunSerumTwinPack2.png?v=1740466747',
