INSERT INTO articles (title, slug, category, author, cover, excerpt, content, tags_json, published) VALUES ('The Rice Water Ritual: Brightening from the First Wash', 'the-rice-water-ritual-brightening-from-the-first-wash', 'Routine', 'Editorial Team', 'https://images.unsplash.com/photo-1570194065650-d99fb4b8ccb0?w=1200&auto=format', 'Rice water has been a Korean beauty staple for generations. Here is how to layer rice-powered skincare into your everyday ritual.', 'Rice water is rich in vitamins, minerals and amino acids that help skin feel softer and look brighter. Start with a rice-based foaming cleanser, follow with a rice toner, and seal everything in with a rice ceramide cream for a dewy, glass-skin finish. Patience is the key — visible change comes from consistency.', '["rice","brightening","korean"]', 1);
INSERT INTO articles (title, slug, category, author, cover, excerpt, content, tags_json, published) VALUES ('SPF Decoded: Choosing the Right Sunscreen for Bondhan Season', 'spf-decoded-choosing-the-right-sunscreen-for-bondhan-season', 'Ingredient Guide', 'Editorial Team', 'https://images.unsplash.com/photo-1611080626919-7cf5a9dbab12?w=1200&auto=format', 'SPF 30 or 50? Chemical or mineral? We break down everything you need to know to pick your perfect daily sunscreen.', 'Look for a broad-spectrum SPF 50 PA++++ for daily wear in humid climates. Gel or watery textures layer beautifully under makeup without heaviness, while rice- and panthenol-infused formulas soothe as they protect. Apply two finger lengths across the face and neck every morning — rain or shine.', '["sunscreen","spf","sun care"]', 1);
INSERT INTO articles (title, slug, category, author, cover, excerpt, content, tags_json, published) VALUES ('Snail Mucin, Explained: The 96% Essence Cult Classic', 'snail-mucin-explained-the-96-essence-cult-classic', 'Ingredient Guide', 'Editorial Team', 'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?w=1200&auto=format', 'The internet is obsessed. We explain why snail mucin has earned its place in routines from Seoul to Dhaka.', 'Snail secretion filtrate is prized for delivering a rich dose of hydrating glycoproteins, hyaluronic acid and glycolic acid. The 96% mucin essence has a light, stringy texture that layers beautifully. It suits most skin types and pairs well after the toner step, before heavier creams.', '["snail mucin","hydration","essence"]', 1);
INSERT INTO articles (title, slug, category, author, cover, excerpt, content, tags_json, published) VALUES ('7-Step Glass Skin Routine for Humid Weather', '7-step-glass-skin-routine-for-humid-weather', 'Routine', 'Editorial Team', 'https://images.unsplash.com/photo-1556228852-6d35a585d566?w=1200&auto=format', 'A realistic, seven-step evening routine built for Bangladeshi humidity — without the heavy finish.', 'Double cleanse to melt sunscreen, tone with a clarifying formula, pat in an essence, layer a brightening serum like niacinamide, apply a light ampoule, then finish with a gel cream or milk moisturizer. Adjust textures by season and keep SPF on during the day.', '["routine","glass skin","skincare"]', 1);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('Are your products 100% authentic?', 'Yes. Every product is sourced through authorized distributors and verified before being listed. Authenticity is the foundation of what we do.', 'general', 1);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('How long does delivery take?', 'Inside Dhaka: 1–2 working days. Outside Dhaka: 2–4 working days. Orders placed before 3 PM usually ship the same day.', 'shipping', 2);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('What is the delivery charge?', 'Delivery inside Dhaka is ৳60 and outside Dhaka is ৳120.', 'shipping', 3);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('Which payment methods do you accept?', 'We accept Cash on Delivery, bKash and Nagad. Our payment team will confirm your order over the phone after you place it.', 'payment', 4);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('How do I track my order?', 'Use the Order Tracking page and enter your Order ID or your phone number to see the live status of your order.', 'orders', 5);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('Can I return or exchange a product?', 'Unopened, unused products can be returned within 7 days of delivery. Please reach out to our support team to arrange a return.', 'returns', 6);
INSERT INTO faqs (question, answer, section, sort_order) VALUES ('How do I find the right products for my skin?', 'Try our "Find Your Routine" quiz — answer a few questions and we will recommend a personalized routine built around your skin type and concerns.', 'general', 7);
INSERT INTO routine_questions (question, subtitle, multiple, sort_order) VALUES ('What is your skin type?', 'Choose the one that describes your skin most days.', 0, 1);
